#!/usr/bin/env python3
"""Create VelaSight architecture diagram via drawio-mcp-server"""
import json, urllib.request, time, sys

MCP_URL = "http://localhost:3000/mcp"
DOC_ID = "176319b5-4ec2-446b-a583-91e7e3388412"
HEADERS = {
    "Content-Type": "application/json",
    "Accept": "application/json, text/event-stream",
}

def call_tool(name, args, req_id):
    body = json.dumps({
        "jsonrpc": "2.0", "id": req_id,
        "method": "tools/call",
        "params": {"name": name, "arguments": args}
    }).encode()
    req = urllib.request.Request(MCP_URL, data=body, headers=HEADERS, method="POST")
    resp = urllib.request.urlopen(req)
    raw = resp.read().decode()
    # Parse server-sent event data
    for line in raw.split("\n"):
        if line.startswith("data: "):
            data = json.loads(line[6:])
            if "result" in data:
                for c in data["result"].get("content", []):
                    if c["type"] == "text":
                        return json.loads(c["text"])
    return None

def add_rect(req_id, x, y, w, h, text, style, layer_label=None):
    args = {
        "target_page": {"index": 0},
        "target_document": {"id": DOC_ID},
        "x": x, "y": y, "width": w, "height": h,
        "text": text, "style": style,
    }
    return call_tool("add-rectangle", args, req_id)

def add_edge(req_id, src_id, tgt_id, text="", style=None):
    if style is None:
        style = "edgeStyle=orthogonalEdgeStyle;rounded=1;orthogonalLoop=1;jettySize=auto;html=1;strokeWidth=2;fontSize=12;"
    args = {
        "target_page": {"index": 0},
        "target_document": {"id": DOC_ID},
        "source_id": src_id, "target_id": tgt_id,
        "text": text, "style": style,
    }
    return call_tool("add-edge", args, req_id)

# ================ CREATE ALL RECTANGLES ================

# Layer 1: Cloud AI (y=30~270)
print("Creating Cloud AI layer...")
r1 = add_rect(101, 50, 30, 1000, 240,
    "云端 AI 服务层 (Cloud AI Services)",
    "whiteSpace=wrap;html=1;fillColor=#E3F2FD;strokeColor=#1565C0;strokeWidth=3;fontStyle=1;fontSize=15;rounded=1;arcSize=8;")
if r1 and "result" in r1:
    print(f"  Layer1 bg: {r1['result']['id']}")

# Components in Layer 1
cpt = "whiteSpace=wrap;html=1;fillColor=#BBDEFB;strokeColor=#1565C0;rounded=1;arcSize=6;fontSize=13;"
r_expr = add_rect(111, 70, 90, 160, 55, "表情识别小模型\n(Expression CNN)", cpt)
r_asr  = add_rect(112, 260, 90, 160, 55, "ASR 语音转写", cpt)
r_llm  = add_rect(113, 450, 85, 200, 65, "多模态大模型 (LLM)\n推理/分析/建议生成", cpt)
r_tts  = add_rect(114, 680, 90, 160, 55, "TTS 语音合成", cpt)
r_ctrl = add_rect(115, 870, 90, 160, 55, "统一会话编排\n(路由/鉴权/校验)", cpt)

ids = {}
for r, name in [(r_expr,"expr"), (r_asr,"asr"), (r_llm,"llm"), (r_tts,"tts"), (r_ctrl,"ctrl")]:
    if r and "result" in r:
        ids[name] = r["result"]["id"]
        print(f"  {name}: {ids[name]}")

# ================ MIDDLE LAYER ================
print("\nCreating Device Application layer...")
r2 = add_rect(201, 50, 300, 1000, 240,
    "端侧应用与 Agent 层 (Device Application & Agent)",
    "whiteSpace=wrap;html=1;fillColor=#FFF3E0;strokeColor=#E65100;strokeWidth=3;fontStyle=1;fontSize=15;rounded=1;arcSize=8;")
if r2 and "result" in r2:
    print(f"  Layer2 bg: {r2['result']['id']}")

cpt2 = "whiteSpace=wrap;html=1;fillColor=#FFE0B2;strokeColor=#E65100;rounded=1;arcSize=6;fontSize=13;"
cpt2a = "whiteSpace=wrap;html=1;fillColor=#FFB74D;strokeColor=#E65100;rounded=1;arcSize=6;fontSize=13;"

r_sm    = add_rect(211, 70, 350, 200, 55, "社交辅助模式状态机\n(Social Assist SM)", cpt2a)
r_cam   = add_rect(212, 310, 350, 180, 55, "Camera 5 FPS\nJPEG 硬件编码", cpt2)
r_audio = add_rect(213, 520, 350, 180, 55, "Audio 16 kHz\nPCM 连续采集", cpt2)
r_fb    = add_rect(214, 730, 350, 200, 55, "震动 / 扬声器 / 屏幕\n(低打扰反馈)", cpt2a)
r_agent = add_rect(215, 70, 430, 200, 50, "ai_agent / Tool / Skill\n(云端降级路径)", cpt2)
r_http  = add_rect(216, 310, 430, 390, 50, "HTTPS 上传 + 隐私控制\n(有界缓冲/TTL/释放)", cpt2)
r_web   = add_rect(217, 740, 430, 200, 50, "板载 Web 管理\n+ KVDB 本地存储", cpt2)

for r, name in [(r_sm,"sm"), (r_cam,"cam"), (r_audio,"audio"), (r_fb,"fb"),
                 (r_agent,"agent"), (r_http,"http"), (r_web,"web")]:
    if r and "result" in r:
        ids[name] = r["result"]["id"]
        print(f"  {name}: {ids[name]}")

# ================ BOTTOM LAYER ================
print("\nCreating System layer...")
r3 = add_rect(301, 50, 570, 1000, 210,
    "系统与多核适配层 (System & Multi-core Adaptation)",
    "whiteSpace=wrap;html=1;fillColor=#E8F5E9;strokeColor=#2E7D32;strokeWidth=3;fontStyle=1;fontSize=15;rounded=1;arcSize=8;")
if r3 and "result" in r3:
    print(f"  Layer3 bg: {r3['result']['id']}")

cpt3 = "whiteSpace=wrap;html=1;fillColor=#C8E6C9;strokeColor=#2E7D32;rounded=1;arcSize=6;fontSize=13;"
cpt3a = "whiteSpace=wrap;html=1;fillColor=#81C784;strokeColor=#1B5E20;rounded=1;arcSize=6;fontSize=13;"

r_vela = add_rect(311, 70, 620, 260, 70, "CPU1 / OpenVela (NuttX)\n内核·驱动(Cam/Audio/PWM)·TCP/IP·TLS", cpt3a)
r_mbx  = add_rect(312, 370, 620, 260, 70, "Mailbox v2 / PWC / Heartbeat\n(跨核逻辑通道·序列·ACK·超时恢复)", cpt3)
r_cp   = add_rect(313, 670, 620, 260, 70, "CPU0 / CP (Armino 原厂固件)\nWi-Fi射频·BLE控制·电源/时钟·Flash代理", cpt3a)
r_tls  = add_rect(314, 370, 710, 260, 50, "TLS/HTTPS 安全链路\n(SNTP → CA → VERIFY_REQUIRED)", cpt3)

for r, name in [(r_vela,"vela"), (r_mbx,"mbx"), (r_cp,"cp"), (r_tls,"tls")]:
    if r and "result" in r:
        ids[name] = r["result"]["id"]
        print(f"  {name}: {ids[name]}")

# ================ PRINT IDS FOR EDGE CREATION ================
print("\n=== Cell IDs for edges ===")
for k, v in ids.items():
    print(f"{k}: {v}")

