#!/usr/bin/env python3
"""Export the draw.io diagram as XML and save to file"""
import json, urllib.request

MCP_URL = "http://localhost:3000/mcp"
HEADERS = {"Content-Type": "application/json", "Accept": "application/json, text/event-stream"}
DOC_ID = "176319b5-4ec2-446b-a583-91e7e3388412"  # from list-documents output

OUTPUT_PATH = "/home/mi/vela_competition/velasight_architecture.drawio"

body = json.dumps({
    "jsonrpc": "2.0", "id": 9999,
    "method": "tools/call",
    "params": {
        "name": "export-diagram",
        "arguments": {
            "target_page": {"index": 0},
            "target_document": {"id": DOC_ID},
            "format": "xml",
        }
    }
}).encode()

req = urllib.request.Request(MCP_URL, data=body, headers=HEADERS, method="POST")
resp = urllib.request.urlopen(req)
raw = resp.read().decode()

xml_content = None
for line in raw.split("\n"):
    if line.startswith("data: "):
        data = json.loads(line[6:])
        if "result" in data:
            for c in data["result"].get("content", []):
                if c["type"] == "text":
                    xml_content = c["text"]
                    break

if xml_content:
    with open(OUTPUT_PATH, "w") as f:
        f.write(xml_content)
    print(f"Success! Diagram saved to: {OUTPUT_PATH}")
    print(f"Size: {len(xml_content)} bytes")
else:
    print("Failed to get XML content")
    print(raw[:2000])

